+// LSD Radix Sort for uint32_t using 11-bit digits (3 passes)
+// Uses ping-pong between array and scratch buffer.
+static void radix_sort_lsd(uint32_t* a, uint32_t* buf, size_t n) {
+    static const int BITS = 11;
+    static const int MASK = (1 << BITS) - 1;
+    static const int NUM_DIGITS = 1 << BITS;
+
+    uint32_t* src = a;
+    uint32_t* dst = buf;
+
+    for (int pass = 0; pass < 3; ++pass) {
+        // Count frequencies
+        uint32_t counts[NUM_DIGITS] = {0};
+        for (size_t i = 0; i < n; ++i) {
+            uint32_t digit = (src[i] >> (pass * BITS)) & MASK;
+            counts[digit]++;
+        }
+
+        // Check if all elements have the same digit in this pass
+        bool all_same = true;
+        for (int i = 1; i < NUM_DIGITS; ++i) {
+            if (counts[i] != 0) {
+                all_same = false;
+                break;
+            }
+        }
+
+        if (all_same) {
+            // No movement needed, but we must ensure src/dst orientation for next pass.
+            // If we don't move, src stays src. Next pass expects src.
+            // However, if pass is odd, we effectively "skipped" a swap.
+            // To keep logic simple, we just continue. src remains valid source.
+            continue;
+        }
+
+        // Compute exclusive prefix sums
+        uint32_t starts[NUM_DIGITS];
+        starts[0] = 0;
+        for (int i = 1; i < NUM_DIGITS; ++i) {
+            starts[i] = starts[i-1] + counts[i-1];
+        }
+
+        // Scatter elements to destination
+        for (size_t i = 0; i < n; ++i) {
+            uint32_t digit = (src[i] >> (pass * BITS)) & MASK;
+            dst[starts[digit]++] = src[i];
+        }
+
+        // Swap src and dst for next pass
+        uint32_t* temp = src;
+        src = dst;
+        dst = temp;
+    }
+
+    // If the result is in the buffer, copy back to a
+    if (src != a) {
+        memcpy(a, src, n * sizeof(uint32_t));
+    }
